import numpy as np
from causallearn.graph.GeneralGraph import GeneralGraph
from causallearn.graph.GraphNode import GraphNode

# =====================================================================
# EDITABLE: implement run_causal_discovery below
# =====================================================================
def run_causal_discovery(X: np.ndarray) -> GeneralGraph:
    """
    Score-based structure search (GES/BDeu) refined by mined logical
    implications: high-confidence association rules are used to (1) prune
    logically-redundant edges, (2) orient undirected edges, and (3) enforce
    consistency via Meek-style propagation.
    """
    from causallearn.search.ScoreBased.GES import ges
    from causallearn.graph.Endpoint import Endpoint
    from causallearn.graph.Edge import Edge

    X = np.asarray(X, dtype=int)
    n, p = X.shape

    # ---------- Step 1: base CPDAG via score-based search ----------
    result = ges(
        X,
        score_func="local_score_BDeu",
        parameters={"sample_prior": 1.0, "structure_prior": 1.0},
    )
    G0 = result["G"]

    # ---------- Step 2: mine pairwise logical implications ----------
    min_support = max(30, int(round(0.02 * n)))
    conf_orient = 0.995   # confidence threshold for orientation-guiding rules
    conf_det = 0.999      # confidence threshold for near-deterministic rules
    imp = np.zeros((p, p))              # weighted implication strength i => j
    det = np.zeros((p, p), dtype=bool)  # det[i, j]: j ~ deterministic func of i

    marg = []
    for j in range(p):
        vals, cnts = np.unique(X[:, j], return_counts=True)
        marg.append(dict(zip(vals.tolist(), (cnts / n).tolist())))

    for i in range(p):
        vi = X[:, i]
        vals_i, cnts_i = np.unique(vi, return_counts=True)
        masks = [
            (int(ca), vi == a)
            for a, ca in zip(vals_i.tolist(), cnts_i.tolist())
            if ca >= min_support
        ]
        for j in range(p):
            if i == j:
                continue
            vj = X[:, j]
            score = 0.0
            det_cov = 0.0
            for ca, m in masks:
                vb, cb = np.unique(vj[m], return_counts=True)
                k = int(np.argmax(cb))
                conf = cb[k] / ca
                pb = marg[j].get(int(vb[k]), 1.0)
                if conf >= conf_orient and pb <= 0.9 and conf >= pb + 0.1:
                    score += (ca / n) * (conf - pb)
                if conf >= conf_det:
                    det_cov += ca / n
            imp[i, j] = score
            det[i, j] = det_cov >= 0.995

    # ---------- extract adjacency structure from GES output ----------
    nodes = G0.get_nodes()
    nmap = G0.node_map
    A = np.zeros((p, p), dtype=int)      # A[i, j] = 1  <=>  i -> j
    und = np.zeros((p, p), dtype=bool)   # undirected i -- j
    for edge in G0.get_graph_edges():
        i = nmap[edge.get_node1()]
        j = nmap[edge.get_node2()]
        e1, e2 = edge.get_endpoint1(), edge.get_endpoint2()
        if e1 == Endpoint.TAIL and e2 == Endpoint.ARROW:
            A[i, j] = 1
        elif e1 == Endpoint.ARROW and e2 == Endpoint.TAIL:
            A[j, i] = 1
        else:
            und[i, j] = und[j, i] = True

    def adjacent(i, j):
        return bool(und[i, j] or A[i, j] or A[j, i])

    # ---------- Step 3: logical-consistency pruning ----------
    # If both i and j are (near-)deterministic functions of a common
    # neighbor k, any i-j dependence is logically explained by k and the
    # direct edge i-j contradicts the mined implications (i _||_ j | k).
    for i in range(p):
        for j in range(i + 1, p):
            if not adjacent(i, j):
                continue
            for k in range(p):
                if k == i or k == j:
                    continue
                if (adjacent(k, i) and adjacent(k, j)
                        and det[k, i] and det[k, j]):
                    und[i, j] = und[j, i] = False
                    A[i, j] = A[j, i] = 0
                    break

    # ---------- Step 4: rule-guided orientation of undirected edges ----------
    def has_dir_path(s, t):
        stack, seen = [s], set()
        while stack:
            u = stack.pop()
            if u == t:
                return True
            if u in seen:
                continue
            seen.add(u)
            for v in np.where(A[u] == 1)[0]:
                if int(v) not in seen:
                    stack.append(int(v))
        return False

    cands = []
    for i in range(p):
        for j in range(i + 1, p):
            if not und[i, j]:
                continue
            si, sj = imp[i, j], imp[j, i]
            # only act on strongly asymmetric implications (self-consistency)
            if si >= 0.2 and si >= 10.0 * sj + 1e-12:
                cands.append((si, i, j))
            elif sj >= 0.2 and sj >= 10.0 * si + 1e-12:
                cands.append((sj, j, i))
    cands.sort(reverse=True)
    for s, i, j in cands:
        if not und[i, j]:
            continue
        if has_dir_path(j, i):          # would create a directed cycle
            continue
        parents_j = [int(k) for k in np.where(A[:, j] == 1)[0]]
        # do not create a new unshielded collider at j
        if any(k != i and not adjacent(k, i) for k in parents_j):
            continue
        und[i, j] = und[j, i] = False
        A[i, j] = 1

    # ---------- Step 5: Meek-style propagation for consistency ----------
    changed = True
    while changed:
        changed = False
        for i in range(p):
            for j in range(p):
                if not und[i, j]:
                    continue
                r1 = any(A[k, i] == 1 and not adjacent(k, j)
                         for k in range(p) if k != i and k != j)
                r2 = any(A[i, k] == 1 and A[k, j] == 1
                         for k in range(p) if k != i and k != j)
                if (r1 or r2) and not has_dir_path(j, i):
                    und[i, j] = und[j, i] = False
                    A[i, j] = 1
                    changed = True

    # ---------- rebuild output graph ----------
    out = GeneralGraph(nodes)
    for i in range(p):
        for j in range(p):
            if A[i, j] == 1:
                out.add_directed_edge(nodes[i], nodes[j])
            elif j > i and und[i, j]:
                out.add_edge(Edge(nodes[i], nodes[j],
                                  Endpoint.TAIL, Endpoint.TAIL))
    return out
# =====================================================================
